from hypothesis import strategies as st
from itertools import product

@st.composite
def gen(draw):
    n = draw(st.integers(2, 7))
    lines = [str(n)]
    for i in range(1, n):
        a = draw(st.integers(1, 10))
        b = draw(st.integers(1, 10))
        x = draw(st.integers(1, n))
        lines.append(f"{a} {b} {x}")
    return "\n".join(lines) + "\n"

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 1:
            return False
        n = int(t[0])
        if not (2 <= n <= 2 * 10**5):
            return False
        if len(t) != 1 + 3 * (n - 1):
            return False
        vals = [int(x) for x in t[1:]]
        for i in range(n - 1):
            a, b, x = vals[3 * i], vals[3 * i + 1], vals[3 * i + 2]
            if not (1 <= a <= 10**9 and 1 <= b <= 10**9 and 1 <= x <= n):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n = int(t[0])
    vals = [int(x) for x in t[1:]]
    A = [0] * (n + 1)
    B = [0] * (n + 1)
    X = [0] * (n + 1)
    for i in range(1, n):
        A[i] = vals[3 * (i - 1)]
        B[i] = vals[3 * (i - 1) + 1]
        X[i] = vals[3 * (i - 1) + 2]
    best = None
    # Enumerate every assignment of an action to each stage 1..N-1.
    # A deterministic walk from stage 1 following the assignment; the
    # optimal play is one such walk (unvisited stages are irrelevant).
    for choice in product((0, 1), repeat=n - 1):
        cur = 1
        cost = 0
        seen = set()
        ok = True
        while cur != n:
            if cur in seen:
                ok = False
                break
            seen.add(cur)
            if choice[cur - 1] == 0:
                cost += A[cur]
                cur = cur + 1
            else:
                cost += B[cur]
                cur = X[cur]
        if ok and (best is None or cost < best):
            best = cost
    return str(best)

